uniform float speed : 0.0 .. 5.0 = 1.0;
uniform float density : 0.0 .. 1.0 = 0.3;
uniform float tail : 0.01 .. 2.0 = 0.5;

state float head[8];
state bool inited;

void update() {
  if (!inited) {
    for (int i = 0; i < 8; i = i + 1) {
      head[i] = hash(float(i));
    }
    inited = true;
  }
  for (int i = 0; i < 8; i = i + 1) {
    head[i] = fract(head[i] + dt * speed * fixed(0.25));
  }
}

vec3 shade(Led led) {
  int seg = led.seg;
  float t = fract(led.s - head[seg]);
  float band = clamp((tail - t) / tail, 0.0, 1.0);
  float spark = step(fixed(1.0) - fixed(density), fixed(led.s));
  return vec3(0.0, 1.0, 0.0) * band * spark;
}
